module mnist_npu_tb; reg clk,rst,start,pixel_we; reg signed [7:0] pixel_in; reg [9:0] pixel_addr; wire busy,done; wire [3:0] predicted_digit; mnist_npu_top dut(.clk(clk),.rst(rst),.start(start),.pixel_in(pixel_in),.pixel_we(pixel_we),.pixel_addr(pixel_addr),.busy(busy),.done(done),.predicted_digit(predicted_digit)); always #5 clk=~clk; integer i; initial begin clk=0;rst=1;start=0;pixel_in=0;pixel_we=0;pixel_addr=0; #20 rst=0; for(i=0;i<784;i=i+1) begin @(posedge clk); pixel_we<=1;pixel_addr<=i;pixel_in<=0; end @(posedge clk);pixel_we<=0;start<=1;@(posedge clk);start<=0;wait(done);$display("Starter controller completed. predicted_digit=%0d",predicted_digit);$display("NOTE: this testbench does not verify MNIST classification accuracy.");$finish;end endmodule
